package com.portfoliolab.backend.research;
import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.client.RestClient;import org.springframework.test.web.client.MockRestServiceServer;import org.springframework.http.MediaType;import java.time.*;import static org.springframework.test.web.client.match.MockRestRequestMatchers.*;import static org.springframework.test.web.client.response.MockRestResponseCreators.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.junit.jupiter.api.Assertions.*;
class ResearchIngestionTests {
 String body(String symbol){return "{\"symbol\":\""+symbol+"\",\"source\":\"fictional-history-v1\",\"interval\":\"1d\",\"candles\":[{\"time\":\"2026-01-01T00:00:00Z\",\"open\":100,\"high\":110,\"low\":90,\"close\":105,\"volume\":1000}]}";}
 @Test void validatesFixtureIdentityAndWritesOnlyIsolatedCache(){var jdbc=mock(JdbcTemplate.class);var builder=RestClient.builder().baseUrl("http://localhost:8081");var server=MockRestServiceServer.bindTo(builder).build();server.expect(requestTo("http://localhost:8081/history?symbol=ALPHA&from=2026-01-01&to=2026-01-02")).andRespond(withSuccess(body("ALPHA"),MediaType.APPLICATION_JSON));new ResearchHistoryStore(jdbc,builder.build()).ingest(5,"ALPHA",LocalDate.of(2026,1,1),LocalDate.of(2026,1,2));verify(jdbc).update(contains("INSERT INTO fictional_market_candles"),eq(5L),any(),any(),any(),any(),any(),eq(1000L));verifyNoMoreInteractions(jdbc);server.verify();}
 @Test void wrongSymbolNeverWrites(){var jdbc=mock(JdbcTemplate.class);var builder=RestClient.builder().baseUrl("http://localhost:8081");var server=MockRestServiceServer.bindTo(builder).build();server.expect(anything()).andRespond(withSuccess(body("OTHER"),MediaType.APPLICATION_JSON));assertThrows(IllegalStateException.class,()->new ResearchHistoryStore(jdbc,builder.build()).ingest(5,"ALPHA",LocalDate.of(2026,1,1),LocalDate.of(2026,1,2)));verifyNoInteractions(jdbc);}
}
